var HOST_ERRORS_FR = [
  [/^Could not reach the mail server at (.+)\. Check the server address\.$/, "Impossible de joindre le serveur de messagerie à l’adresse $1. Vérifiez l’adresse du serveur."],
  [/^Model (.+) is not available\. Available: (.*)$/, "Le modèle $1 n’est pas disponible. Disponibles : $2"],
  [/^The API key for (.+) is set outside DS Bot and cannot be changed here$/, "La clé API de $1 est définie hors de DS Bot et ne peut pas être modifiée ici"],
  [/^(.+) takes no API key here$/, "$1 n’utilise pas de clé API ici"],
  [/^(.+) is already set up$/, "$1 est déjà configuré"],
  [/^DSH offers no provider (.+)$/, "DSH ne propose pas le fournisseur $1"],
  [/^DSH already offers (.+); add it from its list$/, "DSH propose déjà $1 ; ajoutez-le depuis la liste"],
  [/^The protocol must be one of (.+)$/, "Le protocole doit être l’un des suivants : $1"],
  [/^(.+) is not set up$/, "$1 n’est pas configuré"],
  [/^(.+) comes with this setup and cannot be removed$/, "$1 est inclus dans cette configuration et ne peut pas être supprimé"],
  [/^A Bot named (.+) already exists$/, "Un Bot nommé $1 existe déjà"],
  [/^Name (.*) is not available$/, "Le nom $1 n’est pas disponible"],
  [/^"(.+)" calls everyone in a group, so it cannot be a Bot name$/, "« $1 » interpelle tout le monde dans un groupe et ne peut pas servir de nom de Bot"],
  [/^"(.+)" stands for the user in a chat, so it cannot be a Bot name$/, "« $1 » désigne l’utilisateur dans une discussion et ne peut pas servir de nom de Bot"],
  [/^Another group chat is already called "(.+)"$/, "Une autre discussion de groupe s’appelle déjà « $1 »"],
  [/^Another section is already called "(.+)"$/, "Une autre section s’appelle déjà « $1 »"],
  [/^Enter a section name$/, "Saisissez un nom de section"],
  [/^A group chat holds at most (\d+) Bots$/, "Une discussion de groupe peut contenir au maximum $1 Bots"],
  [/^Reply mode must be one of (.+)$/, "Le mode de réponse doit être l’un des suivants : $1"],
  [/^Only the user, a Main Bot, or the admin of "(.+)" can change it$/, "Seuls vous, un Bot principal ou l’admin de « $1 » pouvez le modifier"],
  [/^A key must have at least (\d+) characters$/, "Une clé doit comporter au moins $1 caractères"],
  [/^A key can have at most (\d+) characters$/, "Une clé peut comporter au maximum $1 caractères"],
  [/^(.+) is not saved yet$/, "$1 n’est pas encore enregistré"],
  [/^The Bot team in (.+) is open in another dsh \((.+)\)\. This window shows the team but cannot change it; close the other one and reload\.$/, "L’équipe de Bots dans $1 est déjà ouverte dans une autre instance de dsh ($2). Cette fenêtre affiche l’équipe en lecture seule ; fermez l’autre instance puis rechargez."],
  [/^HTTP (\d+)$/, "Échec de la requête (HTTP $1)"],
  [/^GitHub answered (\d+)$/, "GitHub a répondu $1"],
  [/^Keep the name under (\d+) characters$/, "Le nom ne doit pas dépasser $1 caractères"],
  [/^Give the full path of the folder, not (.+)$/, "Indiquez le chemin complet du dossier, et non $1"],
  [/^The avatar library holds at most (\d+) photos\.$/, "La bibliothèque d’avatars peut contenir au maximum $1 photos."],
  [/^The avatar must be a PNG, JPEG, WebP, or GIF image\. Use a square image; 256x256 is recommended\.$/, "L’avatar doit être une image PNG, JPEG, WebP ou GIF. Utilisez une image carrée (256x256 recommandé)."],
  [/^The avatar image is too large: .+$/, "L’image d’avatar est trop volumineuse"],
  [/^There is no folder at (.+)$/, "Aucun dossier trouvé à l’emplacement $1"],
  [/^(.+) is a file, not a folder$/, "$1 est un fichier, pas un dossier"],
  [/^(.+) holds DeepSeek Harness data, so Bots cannot work there$/, "$1 contient des données de DeepSeek Harness ; les Bots ne peuvent pas y travailler"],
  [/^(.+) needs a folder of its own to be private$/, "$1 a besoin de son propre dossier de travail pour devenir privé"],
  [/^(.+) is a Main Bot, so it cannot be private$/, "$1 est un Bot principal et ne peut donc pas être privé"],
  [/^(.+) is in a group chat, where every member reads what is said\. Remove it from its groups first$/, "$1 fait partie d’une discussion de groupe où chaque membre lit les messages. Retirez-le d’abord de ses groupes"],
  [/^(.+) is private, so it cannot be a Main Bot$/, "$1 est un Bot privé et ne peut donc pas être Bot principal"],
  [/^(.+) is private, so it cannot be copied$/, "$1 est un Bot privé et ne peut pas être dupliqué"],
  [/^(.+) is a private Bot and cannot be in a group chat: what is said in a group is read by every member$/, "$1 est un Bot privé et ne peut pas rejoindre une discussion de groupe : les messages d’un groupe sont lus par tous ses membres"],
  [/^(.+) is in or around the team workspace, so (.+) cannot be private there\. Give it a folder of its own$/, "$1 chevauche l’espace de travail de l’équipe ; $2 ne peut pas y être privé. Donnez-lui un dossier dédié"],
  [/^(.+) is in or around the folder of (.+), so (.+) cannot be private there\. Give it a folder of its own$/, "$1 chevauche le dossier de « $2 » ; $3 ne peut pas y être privé. Donnez-lui un dossier dédié"],
  [/^(.+) is in or around the folder of (.+), a private Bot, so (.+) cannot work there$/, "$1 se trouve dans ou englobe le dossier du Bot privé « $2 » ; $3 ne peut pas y travailler"],
  [/^(.+) is in or around the folder of (.+), a private Bot, so a group cannot work there$/, "$1 se trouve dans ou englobe le dossier du Bot privé « $2 » ; un groupe ne peut pas y travailler"],
  [/^(.+) is in or around the folder of (.+), a private Bot, so it cannot be the team workspace$/, "$1 se trouve dans ou englobe le dossier du Bot privé « $2 » et ne peut donc pas servir d’espace de travail de l’équipe"],
  [/^This looks like a key, token, or password[\s\S]*$/, "Cela ressemble à une clé, un jeton ou un mot de passe ; la mémoire n’enregistre pas ce type d’information"],
  [/^An entry holds at most (\d+) characters; this one has (\d+)\.[\s\S]*$/, "Une entrée peut contenir au maximum $1 caractères ; celle-ci en compte $2."],
  [/^[\s\S]*'s MEMORY\.md would have (\d+) of its (\d+) characters\.[\s\S]*$/, "MEMORY.md atteindrait $1 caractères sur la limite de $2. Supprimez d’abord certaines entrées."],
  [/^The topic \[\[(.+?)\]\] in [\s\S]* would have (\d+) of its (\d+) characters\.[\s\S]*$/, "Le sujet [[$1]] atteindrait $2 caractères sur la limite de $3."],
  [/^[\s\S]* already has (\d+) topics, the most it holds\.[\s\S]*$/, "La limite de $1 sujets est déjà atteinte."],
  [/^There is no entry (.+)\.$/, "L’entrée $1 n’existe pas."],
  [/^No entry in [\s\S]* matches "([\s\S]*)"\.[\s\S]*$/, "Aucune entrée ne correspond à « $1 »."],
  [/^"([\s\S]*)" matches (\d+) entries in [\s\S]*$/, "« $1 » correspond à $2 entrées ; soyez plus précis."],
  [/^Memory cannot change now: [\s\S]*$/, "Impossible de modifier la mémoire maintenant : une autre instance de dsh utilise cette équipe de Bots"]
];
